# Part of the Sellora test suite. Needs: pip install playwright pillow  and  python -m playwright install chromium
import os as _os, pathlib as _pl
HERE=_os.path.dirname(_os.path.abspath(__file__)); _os.chdir(HERE); _os.makedirs('shots',exist_ok=True)
APP=_os.path.abspath(_os.path.join(HERE,'..','Sellora_Seller_Center.html')); APP_URL=_pl.Path(APP).as_uri()
from playwright.sync_api import sync_playwright
URL=APP_URL; R=[]
def check(n,c,i=''): R.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+(' | '+str(i) if i else ''))
W=lambda pg,ms=150: pg.wait_for_timeout(ms)
D="JSON.parse(localStorage.getItem('sellora-d-a@mail.com'))"
def pv(pg,name): return pg.evaluate("[].slice.call(document.querySelectorAll('#items select option')).filter(o=>o.textContent.indexOf('"+name+"')===0)[0].value")
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={'width':1280,'height':900}); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(URL); W(pg,250); pg.fill('#l-name','S'); pg.fill('#l-email','a@mail.com'); pg.fill('#l-pass','secret12'); pg.click('#lf button[type=submit]'); W(pg,300)
    pg.click('[data-act=sample]'); W(pg,300)
    pg.click('.navb[data-p=products]'); pg.click('main [data-act=addProd]'); W(pg); pg.fill('#f-name','Bag'); pg.fill('#f-price','300'); pg.fill('#f-stock','20'); pg.fill('#f-low','5'); pg.click('#pf button[type=submit]'); W(pg)
    pg.click('.navb[data-p=marketing]'); W(pg); pg.fill('#c-code','TEN'); pg.fill('#c-val','10'); pg.fill('#c-exp','2030-01-01'); pg.click('#cf button[type=submit]'); W(pg)
    # ---- Back button ----
    pg.click('.navb[data-p=dashboard]'); W(pg); pg.click('.navb[data-p=orders]'); W(pg)
    pg.click('main [data-act=addOrder]'); W(pg); pg.go_back(); W(pg,300)
    check('Back with an untouched form: form closes, you stay on Orders', pg.query_selector('#of') is None and pg.inner_text('main h1')=='Orders' and pg.evaluate('location.hash')=='#orders')
    pg.click('main [data-act=addOrder]'); W(pg); pg.fill('#o-note','keep me'); pg.go_back(); W(pg,300)
    check('Back with typing: asks first, URL stays', pg.query_selector('[data-act=discardYes]') is not None and pg.evaluate('location.hash')=='#orders')
    pg.click('[data-act=discardNo]'); W(pg); check('Keep editing: text still there', pg.input_value('#o-note')=='keep me')
    pg.go_back(); W(pg,300); pg.click('[data-act=discardYes]'); W(pg)
    check('Discard: form gone, still on Orders', pg.query_selector('#of') is None and pg.inner_text('main h1')=='Orders')
    pg.go_back(); W(pg,300); check('Back again (no form open) goes to the previous page', 'Good' in pg.inner_text('main h1') or pg.evaluate('location.hash')=='#dashboard', pg.evaluate('location.hash'))
    # ---- order with coupon TEN, paid ----
    pg.click('.navb[data-p=orders]'); pg.click('main [data-act=addOrder]'); W(pg); pg.select_option('#o-cust',index=1); pg.select_option('#items select',pv(pg,'Bag')); pg.fill('[data-f=qty]','2'); pg.select_option('#o-coupon','TEN'); W(pg); pg.click('#of button[type=submit]'); W(pg,300)
    oid=pg.evaluate(D+".orders.slice(-1)[0].id"); o=pg.evaluate(D+f".orders.find(o=>o.id==={oid})")
    check('new order stores its coupon terms', o['cterm']=={'type':'Percentage','val':10,'min':0} and o['disc']==60, o['cterm'])
    idx=pg.evaluate(D+".coupons.findIndex(c=>c.code==='TEN')"); pg.click('.navb[data-p=marketing]'); W(pg); pg.click(f'[data-act=editCoupon][data-id="{idx}"]'); W(pg); pg.fill('#ce-val','50'); pg.click('#cef button[type=submit]'); W(pg)
    pg.goto(URL+f'#orders/{oid}'); W(pg,300); pg.click('[data-act=editOrder]'); W(pg)
    check('edit form shows the original discount', pg.input_value('#o-disc')=='60', pg.input_value('#o-disc'))
    pg.fill('[data-f=qty]','3'); W(pg)
    check('more items: discount uses the order\'s own 10% (not the coupon\'s new 50%)', pg.input_value('#o-disc')=='90', pg.input_value('#o-disc'))
    # ---- paid total up: back to editing / not yet / yes ----
    pg.click('#of button[type=submit]'); W(pg)
    check('paid order total up: asks about the extra payment', pg.query_selector('#paycheck') is not None and '฿270' in pg.inner_text('#paycheck'), pg.inner_text('#paycheck .mb').split('\n')[0] if pg.query_selector('#paycheck') else '')
    pg.keyboard.press('Tab'); pg.keyboard.press('Tab'); pg.keyboard.press('Tab'); check('focus stays inside the question', pg.evaluate("!!document.activeElement.closest('#paycheck')"))
    pg.keyboard.press('Escape'); W(pg)
    check('Esc: back to editing, nothing saved', pg.query_selector('#paycheck') is None and pg.query_selector('#of') is not None and pg.evaluate(D+f".orders.find(o=>o.id==={oid}).items[0].qty")==2)
    pg.click('#of button[type=submit]'); W(pg); pg.click('[data-act=payDiff][data-v=unpaid]'); W(pg,300)
    o=pg.evaluate(D+f".orders.find(o=>o.id==={oid})")
    check('"Not yet": order part paid, ฿580 kept as paid (no longer only a note)', o['pay']=='Pending' and o.get('paidAmt')==580 and o['items'][0]['qty']==3, (o['pay'],o.get('paidAmt')))
    pg.click('[data-act=markPaid]'); W(pg); pg.click('[data-act=editOrder]'); W(pg); pg.fill('[data-f=qty]','4'); W(pg); pg.click('#of button[type=submit]'); W(pg); pg.click('[data-act=payDiff][data-v=paid]'); W(pg,300)
    o=pg.evaluate(D+f".orders.find(o=>o.id==={oid})")
    check('"Yes, it is paid": stays Paid with the new total', o['pay']=='Paid' and o['items'][0]['qty']==4 and o['disc']==120, (o['pay'],o['disc']))
    pg.click('[data-act=editOrder]'); W(pg); pg.fill('[data-f=qty]','1'); W(pg); pg.click('#of button[type=submit]'); W(pg,300)
    check('paid order total down: no question, toast says refund', pg.query_selector('#paycheck') is None and 'refund' in pg.inner_text('#toast'), pg.inner_text('#toast'))
    # ---- shipping hint ----
    pg.click('[data-act=editOrder]'); W(pg); pg.fill('[data-f=qty]','5'); W(pg)
    hint=pg.inner_text('#o-shiphint'); pg.click('[data-act=useAutoShip]'); W(pg)
    check('shipping hint + "Use ฿0" sets free shipping', 'usual fee' in hint and pg.input_value('#o-ship')=='0' and pg.inner_text('#o-shiphint')=='', hint)
    pg.keyboard.press('Escape'); W(pg); pg.click('[data-act=discardYes]'); W(pg)
    pg.click('[data-act=editOrder]'); W(pg); check('no shipping hint when you only open the edit form', pg.inner_text('#o-shiphint')=='')
    pg.keyboard.press('Escape'); W(pg)
    # ---- old order without stored terms ----
    pg.evaluate("(()=>{const k='sellora-d-a@mail.com',s=JSON.parse(localStorage.getItem(k));const o=s.orders.find(o=>o.coupon==='SAVE100'&&o.status==='Processing');o.cterm=null;window.__old=o.id;localStorage.setItem(k,JSON.stringify(s))})()")
    old=pg.evaluate("window.__old"); pg.reload(); W(pg,300); pg.goto(URL+f'#orders/{old}'); W(pg,300)
    d0=pg.evaluate(D+f".orders.find(o=>o.id==={old}).disc"); pg.click('[data-act=editOrder]'); W(pg); pg.fill('#o-note','old order'); pg.click('#of button[type=submit]'); W(pg,300)
    check('older order without saved terms: editing the note keeps its discount', pg.evaluate(D+f".orders.find(o=>o.id==={old}).disc")==d0, d0)
    # ---- stock alerts on real crossings only ----
    n0=pg.evaluate("+((document.querySelector('[data-act=bell] .dot')||{}).textContent||0)")
    pg.goto(URL+f'#orders/{oid}'); W(pg,300); pg.click('[data-act=editOrder]'); W(pg); pg.fill('[data-f=qty]','16'); pg.click('#of button[type=submit]'); W(pg)
    if pg.query_selector('[data-act=payDiff]'): pg.click('[data-act=payDiff][data-v=paid]'); W(pg,300)
    st=pg.evaluate(D+".products.find(p=>p.name==='Bag').stock"); n1=pg.evaluate("+((document.querySelector('[data-act=bell] .dot')||{}).textContent||0)")
    check('edit that takes stock below the alert line: exactly one Low Stock alert', n1==n0+1 and st==4, f'stock {st}, bell {n0}->{n1}')
    pg.click('[data-act=editOrder]'); W(pg); pg.fill('#o-note','again'); pg.click('#of button[type=submit]'); W(pg,300)
    check('then editing the note: no new alert', pg.evaluate("+((document.querySelector('[data-act=bell] .dot')||{}).textContent||0)")==n1)
    # ---- toast on phone with form open ----
    pg.set_viewport_size({'width':375,'height':812}); W(pg,200); pg.click('[data-act=editOrder]'); W(pg); pg.fill('#o-note','n'); pg.click('#of button[type=submit]'); W(pg,100); pg.click('[data-act=editOrder]'); W(pg,100)
    pos=pg.evaluate("(()=>{const t=document.querySelector('.toast');if(!t)return null;const r=t.getBoundingClientRect();return [Math.round(r.top),getComputedStyle(t).pointerEvents]})()")
    check('phone: toast moves to the top while a form is open and never blocks taps', pos and pos[0]<80 and pos[1]=='none', pos)
    check('no page errors', not errs, errs[:2])
    b.close()
print(f'\n{sum(R)}/{len(R)} passed')
